sys_script_include.script:
var AppReadyResponseService = Class.create();
AppReadyResponseService.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    initialize: function() {},

    saveResponse: function() {
        var applicationId = this.getParameter('sysparm_application_id');
        var questionId = this.getParameter('sysparm_question_id');
        var responseValue = this.getParameter('sysparm_response_value');
        var responseJson = this.getParameter('sysparm_response_json');
        var gr = new GlideRecord('x_1433041_identi_0_response');
        gr.addQuery('application', applicationId);
        gr.addQuery('question', questionId);
        gr.query();
        if (gr.next()) {
            gr.setValue('response_value', responseValue || '');
            if (responseJson) { gr.setValue('response_json', responseJson); }
            gr.setValue('answered_by', gs.getUserID());
            gr.setValue('answered_at', new GlideDateTime().getDisplayValue());
            gr.update();
        } else {
            gr.initialize();
            gr.setValue('application', applicationId);
            gr.setValue('question', questionId);
            gr.setValue('response_value', responseValue || '');
            if (responseJson) { gr.setValue('response_json', responseJson); }
            gr.setValue('answered_by', gs.getUserID());
            gr.setValue('answered_at', new GlideDateTime().getDisplayValue());
            gr.insert();
        }
        var appGr = new GlideRecord('x_1433041_identi_0_application');
        if (appGr.get(applicationId)) {
            appGr.setValue('last_saved_at', new GlideDateTime().getDisplayValue());
            appGr.setValue('last_activity_by', gs.getUserID());
            appGr.update();
        }
        return JSON.stringify({ success: true, message: 'Response saved' });
    },

    saveBatchResponses: function() {
        var applicationId = this.getParameter('sysparm_application_id');
        var responsesJson = this.getParameter('sysparm_responses');
        var responses = JSON.parse(responsesJson);
        var savedCount = 0;
        for (var i = 0; i < responses.length; i++) {
            var resp = responses[i];
            var gr = new GlideRecord('x_1433041_identi_0_response');
            gr.addQuery('application', applicationId);
            gr.addQuery('question', resp.question_id);
            gr.query();
            if (gr.next()) {
                gr.setValue('response_value', resp.value || '');
                if (resp.json) { gr.setValue('response_json', resp.json); }
                gr.setValue('answered_by', gs.getUserID());
                gr.setValue('answered_at', new GlideDateTime().getDisplayValue());
                gr.update();
            } else {
                gr.initialize();
                gr.setValue('application', applicationId);
                gr.setValue('question', resp.question_id);
                gr.setValue('response_value', resp.value || '');
                if (resp.json) { gr.setValue('response_json', resp.json); }
                gr.setValue('answered_by', gs.getUserID());
                gr.setValue('answered_at', new GlideDateTime().getDisplayValue());
                gr.insert();
            }
            savedCount++;
        }
        var appGr = new GlideRecord('x_1433041_identi_0_application');
        if (appGr.get(applicationId)) {
            appGr.setValue('last_saved_at', new GlideDateTime().getDisplayValue());
            appGr.setValue('last_activity_by', gs.getUserID());
            appGr.update();
        }
        return JSON.stringify({ success: true, saved_count: savedCount });
    },

    loadResponses: function() {
        var applicationId = this.getParameter('sysparm_application_id');
        var responses = [];
        var gr = new GlideRecord('x_1433041_identi_0_response');
        gr.addQuery('application', applicationId);
        gr.query();
        while (gr.next()) {
            responses.push({
                sys_id: gr.getUniqueValue(),
                question: gr.getValue('question'),
                response_value: gr.getValue('response_value'),
                response_json: gr.getValue('response_json'),
                answered_by: gr.getValue('answered_by'),
                answered_at: gr.getValue('answered_at')
            });
        }
        return JSON.stringify({ success: true, responses: responses });
    },

    type: 'AppReadyResponseService'
});
